/dts-v1/;

#include "imx8mm-mini.dtsi"

/ {
	model = "Sensor Hub (i.MX8M Mini, 2 GB)";
	compatible = "acme,sensor-hub", "fsl,imx8mm";

	chosen {
		stdout-path = &uart2;
	};

	memory@40000000 {
		reg = <0x0 0x40000000 0 0x80000000>;
	};
};

&{/soc@0/bus@30800000/serial@30890000} {
	status = "okay";
};

&i2c3 {
	clock-frequency = <400000>;
	status = "okay";

	pmic@4b {
		compatible = "rohm,bd71847";
		reg = <0x4b>;
		interrupt-parent = <&gpio1>;
		interrupts = <3 IRQ_TYPE_LEVEL_LOW>;
	};

	imu@6a {
		compatible = "st,ism330dhcx";
		reg = <0x6a>;
		interrupt-parent = <&gpio1>;
		interrupts = <7 IRQ_TYPE_EDGE_RISING>;
	};
};

/* no Cortex-M4 firmware on this board: give the RAM back to Linux */
/delete-node/ &m4_reserved;

